import { mkdir, readdir, readFile, writeFile } from "node:fs/promises";
import { query, type SessionKey, type SessionStore, type SessionStoreEntry } from "@anthropic-ai/claude-agent-sdk";

class FolderSessionStore implements SessionStore {
  #seq = 0;
  #dir(key: SessionKey): string {
    return `store/${key.projectKey}/${key.sessionId}${key.subpath ? `/${key.subpath}` : ""}`;
  }
  async append(key: SessionKey, entries: SessionStoreEntry[]): Promise<void> {
    const dir = this.#dir(key);
    await mkdir(dir, { recursive: true });
    const name = `part-${Date.now()}-${String(this.#seq++).padStart(6, "0")}.jsonl`; // wall clock: later parts sort later
    await writeFile(`${dir}/${name}`, entries.map((e) => JSON.stringify(e)).join("\n"));
    console.log("store: appended", entries.length, "entries to", name);
  }

  async load(key: SessionKey): Promise<SessionStoreEntry[] | null> {
    const dir = this.#dir(key);
    const parts = (await readdir(dir).catch(() => [] as string[])).filter((f) => f.startsWith("part-")).sort();
    if (parts.length === 0) return null; // never written: the SDK starts fresh
    const lines = await Promise.all(parts.map((p) => readFile(`${dir}/${p}`, "utf8")));
    console.log("store: loaded", parts.length, "parts");
    return lines.join("\n").split("\n").filter(Boolean).map((l) => JSON.parse(l) as SessionStoreEntry);
  }
  async listSubkeys(key: { projectKey: string; sessionId: string }): Promise<string[]> {
    const names = await readdir(this.#dir(key), { withFileTypes: true }).catch(() => []);
    return names.filter((d) => d.isDirectory()).map((d) => d.name); // subagent transcripts, if any
  }
}

const resume = process.argv[2]; // second run: pass the session id printed by the first
const prompt = resume ? "Which flower did I ask you to remember?" : "Remember the word tulip. Reply with: noted.";
for await (const msg of query({
  prompt,
  options: {
    model: "claude-haiku-5-5",
    effort: "low",
    tools: [],
    cwd: process.cwd(), // the same cwd both times: it becomes the store's projectKey
    settingSources: [],
    sessionStore: new FolderSessionStore(),
    resume,
    env: { ...process.env, CLAUDE_CONFIG_DIR: resume ? "/tmp/fresh-vm-config" : process.env.CLAUDE_CONFIG_DIR }, // run 2 pretends to be a new VM
  },
})) {
  if (msg.type === "system" && msg.subtype === "mirror_error") console.log("store failed:", msg.error);
  if (msg.type === "result" && msg.subtype === "success") console.log("said:", msg.result, "\nsession_id:", msg.session_id);
}

import type { SessionKey, SessionStore, SessionStoreEntry } from "@anthropic-ai/claude-agent-sdk/core";

export class BrokerS3SessionStore implements SessionStore {
  readonly #seen = new Set<string>(); // entry uuids already stored
  #seq = 0;
  constructor(private readonly broker: BrokerClient) {}

  #prefix(key: SessionKey): string {
    return `sessions/${key.projectKey}/${key.sessionId}${key.subpath ? `/${key.subpath}` : ""}`;
  }

  async append(key: SessionKey, entries: SessionStoreEntry[]): Promise<void> {
    const fresh = entries.filter((e) => !(typeof e.uuid === "string" && this.#seen.has(e.uuid))); // retried batches repeat
    if (fresh.length === 0) return;
    // Wall-clock time, not a per-process counter: parts written later on another VM must sort after these.
    const name = `${this.#prefix(key)}/part-${Date.now()}-${String(this.#seq++).padStart(6, "0")}.jsonl`;
    const res = await fetch(await this.broker.artifactUrl(name, { write: true }), { method: "PUT", body: fresh.map((e) => JSON.stringify(e)).join("\n") });
    if (!res.ok) throw new Error(`session store PUT failed: ${res.status}`); // the SDK retries, then reports mirror_error
    for (const e of fresh) if (typeof e.uuid === "string") this.#seen.add(e.uuid);
  }

  async load(key: SessionKey): Promise<SessionStoreEntry[] | null> {
    const parts = await this.broker.listArtifacts(`${this.#prefix(key)}/part-`); // sorted by name = by time
    if (parts.length === 0) return null;
    const entries: SessionStoreEntry[] = [];
    for (const part of parts) {
      const body = await (await fetch(await this.broker.artifactUrl(part, { write: false }))).text();
      entries.push(...body.split("\n").filter(Boolean).map((line) => JSON.parse(line) as SessionStoreEntry));
    }
    return entries;
  }

  async listSubkeys(key: { projectKey: string; sessionId: string }): Promise<string[]> {
    return this.broker.listSubkeys(this.#prefix(key)); // restores subagent transcripts too
  }
}
